String a = "test";
String b = "test";
String c = new String("test");
System.out.println(a == b);      // true - oba literaly z tej samej puli
System.out.println(a == c);      // false - c to osobny obiekt utworzony przez new
System.out.println(a.equals(c)); // true - zawartosc identyczna
// String Pool przechowuje literaly - a i b wskazuja na TEN SAM obiekt w puli,
// ale new String() ZAWSZE tworzy nowy obiekt POZA pula, nawet o identycznej tresci.

