for (char c : text.toLowerCase().toCharArray()) {
    if (vowels.indexOf(c) != -1) {
        count++;
    }
}
System.out.println("Samogloski: " + count);

String sentence = "Ucze sie Javy";
String[] words = sentence.split(" ");
StringBuilder result = new StringBuilder();
for (int i = words.length - 1; i >= 0; i--) {
    result.append(words[i]);
    if (i > 0) {
        result.append(" ");
    }
}
System.out.println(result);

String a = new String("hello");
String b = new String("hello");
System.out.println(a == b);                 // false - dwa rozne obiekty utworzone przez new
System.out.println(a.intern() == b.intern()); // true - oba intern() zwracaja TEN SAM obiekt z puli
// intern() sprawdza String Pool: jesli taka tresc juz tam jest, zwraca ISTNIEJACY obiekt z puli,
// w przeciwnym razie DODAJE dany String do puli i zwraca go.

