for (String row : rows) {
    String[] columns = row.split(",");
    System.out.println(java.util.Arrays.toString(columns));
}

String text = "java jest super java jest popularny java";
String[] words = text.split(" ");
int count = 0;
for (String word : words) {
    if (word.equals("java")) {
        count++;
    }
}
System.out.println("Wystapien 'java': " + count);

String camel = "myVariableName";
StringBuilder snake = new StringBuilder();
for (char c : camel.toCharArray()) {
    if (Character.isUpperCase(c)) {
        snake.append("_").append(Character.toLowerCase(c));
    } else {
        snake.append(c);
    }
}
System.out.println(snake);

String tag = "p";
String content = "Witaj, swiecie!";
StringBuilder htmlTag = new StringBuilder();
htmlTag.append("<").append(tag).append(">").append(content).append("</").append(tag).append(">");
System.out.println(htmlTag);

StringBuilder document = new StringBuilder();
document.append("<html><body>")
        .append("<h1>Moja strona</h1>")
        .append(htmlTag)
        .append("</body></html>");
System.out.println(document);

